[100000] = {id = 100000, name = "Energy\u{0020}Crystal", icon = "icon_goods_nengyuanjingti", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Cubic\u{0020}crystalline\u{0020}refined\u{0020}from\u{0020}Prime\u{0020}Nimbus\u{0020}Crystals,\u{0020}a\u{0020}usable\u{0020}form\u{0020}of\u{0020}Nimbus\u{0020}that\u{0020}can\u{0020}be\u{0020}used\u{0020}for\u{0020}further\u{0020}processing\u{0020}and\u{0020}applications.\u{0020}Even\u{0020}in\u{0020}a\u{0020}tiny\u{0020}amount,\u{0020}they\u{0020}have\u{0020}potentials\u{0020}to\u{0020}achieve\u{0020}infinite\u{0020}possibilities.\n\"It's\u{0020}a\u{0020}pity\u{0020}that\u{0020}we\u{0020}only\u{0020}managed\u{0020}to\u{0020}extract\u{0020}a\u{0020}tiny\u{0020}amount\u{0020}of\u{0020}it\u{0020}from\u{0020}a\u{0020}large\u{0020}lump\u{0020}of\u{0020}Prime\u{0020}Crystals,\u{0020}what\u{0020}a\u{0020}waste!\"", group = 4998, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "原初结晶", "从原初尼姆比斯结晶中开采出的矿石，较为稀少。\n「结晶一旦被开采出来，便会被用于制作幻化核心。」\n「市面上很少有流通在外的结晶。」", "0"},
[100001] = {id = 100001, name = "Shield\u{0020}Credits", icon = "icon_goods_dunbi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "Official\u{0020}currency\u{0020}issued\u{0020}by\u{0020}AEGIS\u{0020}globally\u{0020}after\u{0020}the\u{0020}establishment\u{0020}of\u{0020}seven\u{0020}administrative\u{0020}regions.\n\n\"Issued\u{0020}by\u{0020}AEGIS\u{0020}in\u{0020}year\u{0020}2000.\"\n\"The\u{0020}one\u{0020}and\u{0020}only\u{0020}legal\u{0020}currency\u{0020}of\u{0020}the\u{0020}world.\"", group = 100, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "盾币", "艾吉斯设立七大区后统一发行的货币，通行于世界。\n「艾吉斯于2000年发行的货币。」\n「是目前世界上唯一流通且合法的货币。」", "0"},
[100002] = {id = 100002, name = "Elite\u{0020}Token", icon = "icon_goods_jingyingjinianbi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_yx_jyyx_01", txt = "Tokens\u{0020}acquired\u{0020}by\u{0020}participating\u{0020}in\u{0020}Elite\u{0020}Drill.\u{0020}Can\u{0020}be\u{0020}used\u{0020}to\u{0020}buy\u{0020}items\u{0020}in\u{0020}Elite\u{0020}Shop.\n\n\"Completing\u{0020}an\u{0020}Elite\u{0020}Drill\u{0020}is\u{0020}a\u{0020}proof\u{0020}of\u{0020}you\u{0020}have\u{0020}already\u{0020}acquired\u{0020}the\u{0020}knowledge\u{0020}and\u{0020}experience\u{0020}needed\u{0020}for\u{0020}fighting\u{0020}in\u{0020}the\u{0020}frontmost.\u{0020}To\u{0020}conclude,\u{0020}as\u{0020}usual......\u{0020}I'm\u{0020}proud\u{0020}of\u{0020}you\u{0020}all.\u{0020}I\u{0020}wish\u{0020}you\u{0020}all\u{0020}return\u{0020}in\u{0020}one\u{0020}piece,\u{0020}when\u{0020}I\u{0020}see\u{0020}you\u{0020}again.\"", group = 101, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "精英纪念币", "参与精英演习后发放的纪念币，可以在【精英商店】中购买物品。\n「完成了精英演习意味着——你们已经拥有踏足最前线的经验与实力，还是那句老话……你们是我最骄傲的学生，别死了。」", "0"},
[100003] = {id = 100003, name = "Freshman\u{0020}Token", icon = "icon_goods_xinruijinianbi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "The\u{0020}tokens\u{0020}awarded\u{0020}after\u{0020}participating\u{0020}in\u{0020}the\u{0020}Freshman\u{0020}Drill\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}purchase\u{0020}items\u{0020}in\u{0020}the\u{0020}[Freshman\u{0020}Shop].\n\"Congratulations\u{0020}on\u{0020}passing\u{0020}the\u{0020}Freshman\u{0020}Drill.\u{0020}From\u{0020}now\u{0020}on,\u{0020}you\u{0020}will\u{0020}step\u{0020}onto\u{0020}the\u{0020}real\u{0020}battlefield...\u{0020}return\u{0020}alive\u{0020}to\u{0020}see\u{0020}me.\"", group = 102, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "新锐纪念币", "参与新锐演习后发放的纪念币，可以在【新锐商店】中购买物品。\n「恭喜你们通过新锐演习，自此以后你们就将踏上真正的战场……活着回来见我。」", "0"},
[100004] = {id = 100004, name = "Crusade\u{0020}Token", icon = "icon_goods_taofabi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_lhtf_01", txt = "The\u{0020}tokens\u{0020}issued\u{0020}after\u{0020}participating\u{0020}in\u{0020}a\u{0020}Joint\u{0020}Crusade\u{0020}campaign.\u{0020}Can\u{0020}be\u{0020}used\u{0020}to\u{0020}buy\u{0020}items\u{0020}in\u{0020}Campaign\u{0020}Exchange.\n\n\"......Attacks\u{0020}of\u{0020}Major\u{0020}Sins\u{0020}has\u{0020}been\u{0020}getting\u{0020}frequent\u{0020}recently.\u{0020}Our\u{0020}squad\u{0020}leader\u{0020}has\u{0020}a\u{0020}bad\u{0020}feeling;\u{0020}she\u{0020}is\u{0020}considering\u{0020}a\u{0020}reassignment\u{0020}further\u{0020}away\u{0020}from\u{0020}the\u{0020}frontlines\u{0020}would\u{0020}be\u{0020}a\u{0020}better\u{0020}choice...\u{0020}But\u{0020}we're\u{0020}the\u{0020}front\u{0020}line\u{0020}soldiers,\u{0020}if\u{0020}we\u{0020}choose\u{0020}to\u{0020}flee,\u{0020}then\u{0020}what\u{0020}about\u{0020}everyone\u{0020}else...\u{0020}No...\u{0020}we'll\u{0020}stay.\"", group = 103, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "讨伐币", "参与原罪联合讨伐后发放的货币，可以在【联合商店】中购买物品。\n「——最近准罪级的原罪出现得有点频繁，队长预感到之后会有大事情要发生，她觉得现在调离前线也许是最好的选择……但如果连最前线的我们都选择逃避，大家该怎么办啊……不行……我们得留在这。」", "0"},
[100005] = {id = 100005, name = "Daily\u{0020}Token", icon = "icon_goods_jiajubi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_jy_yzts_01", txt = "Tokens\u{0020}issued\u{0020}to\u{0020}Navigators\u{0020}and\u{0020}Drivers\u{0020}as\u{0020}subsidies\u{0020}for\u{0020}daily\u{0020}expenses.\u{0020}Can\u{0020}be\u{0020}used\u{0020}to\u{0020}buy\u{0020}items\u{0020}in\u{0020}Logistics\u{0020}Shop.\n\"Hmm\u{0020}♪\u{0020}Hm-hmm\u{0020}♪\u{0020}No\u{0020}more\u{0020}dish-washing\u{0020}♪\u{0020}Imma\u{0020}buying\u{0020}a\u{0020}dish\u{0020}washer\u{0020}♪\nIt\u{0020}is\u{0020}a\u{0020}precious\u{0020}recording\u{0020}of\u{0020}one\u{0020}Driver\u{0020}spending\u{0020}Daily\u{0020}Token\u{0020}on\u{0020}home\u{0020}appliances\u{0020}for\u{0020}the\u{0020}first\u{0020}time.\u{0020}The\u{0020}jingle\u{0020}has\u{0020}become\u{0020}widespread\u{0020}since\u{0020}then,\u{0020}and\u{0020}that\u{0020}paricular\u{0020}Driver\u{0020}is\u{0020}hence\u{0020}nicknamed\u{0020}'The\u{0020}Shop\u{0020}Pixie'.\"", group = 104, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "日用代币", "发放给领航与驾驶员的日用补贴代币，可以在【后勤商店】中购买物品。\n「——哼♪~哼哼~~不用洗碗啦♪~我要购入一个洗碗机♪~\n这是某位驾驶员初次使用日用代币选购家具的珍贵记录，在这之后这段哼唱被大家广为流传，该驾驶员也被戏称为“后勤店妖精”。」", "0"},
[100006] = {id = 100006, name = "Battlegroup\u{0020}Token", icon = "icon_goods_gonghuibi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Rewards\u{0020}for\u{0020}navigators\u{0020}who\u{0020}contribute\u{0020}to\u{0020}the\u{0020}battlegroup,\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}purchase\u{0020}items\u{0020}in\u{0020}the\u{0020}[Battlegroup\u{0020}Shop].\n\"May\u{0020}your\u{0020}path\u{0020}ahead\u{0020}no\u{0020}longer\u{0020}be\u{0020}lonely.\"", group = 105, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "公会币", "奖励给为公会做出贡献的领航，可以在【公会供给】中购买物品。\n「愿你前行的道路上不再孤单。」", "0"},
[100007] = {id = 100007, name = "Friendship\u{0020}Token", icon = "icon_goods_youqingbi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_wjxq_zyjs_01", txt = "Token\u{0020}of\u{0020}reward\u{0020}and\u{0020}appreciation\u{0020}to\u{0020}Navigators\u{0020}who\u{0020}have\u{0020}provided\u{0020}aid\u{0020}to\u{0020}their\u{0020}fellows.\u{0020}Can\u{0020}be\u{0020}used\u{0020}to\u{0020}buy\u{0020}items\u{0020}in\u{0020}Friendship\u{0020}Shop.\n\n\"May\u{0020}you\u{0020}have\u{0020}someone\u{0020}to\u{0020}help\u{0020}you\u{0020}at\u{0020}your\u{0020}hard\u{0020}times.\"", group = 106, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "友情币", "奖励多次在战场上帮助同僚的领航，可以在【友情商店】中购买物品。\n「愿你在困境中有人相助。」", "0"},
[100008] = {id = 100008, name = "Prime\u{0020}Crystalline", icon = "icon_goods_yuanchujiejing", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_sc_cz_01", txt = "Rare\u{0020}elements\u{0020}mined\u{0020}from\u{0020}the\u{0020}Prime\u{0020}Nimbus\u{0020}Crystal.\u{0020}\n\n\"Once\u{0020}extracted,\u{0020}it\u{0020}will\u{0020}be\u{0020}used\u{0020}in\u{0020}creation\u{0020}of\u{0020}Transformation\u{0020}Cores.\"\n\"It's\u{0020}an\u{0020}extremely\u{0020}rare\u{0020}sight\u{0020}in\u{0020}even\u{0020}open\u{0020}markets.\"", group = 4999, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, timelimt = "0", "0", "原初结晶", "从原初尼姆比斯结晶中开采出的矿石，较为稀少。\n「结晶一旦被开采出来，便会被用于制作幻化核心。」\n「市面上很少有流通在外的结晶。」", "0"},
[110000] = {id = 110000, name = "Diluted\u{0020}Energy\u{0020}Potion", icon = "icon_goods_tiliyaoji_2", quality = 2, use = 1, fall = "4_100001_30", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "A\u{0020}small\u{0020}potion\u{0020}of\u{0020}diluted\u{0020}doses\u{0020}of\u{0020}Nimbus\u{0020}energy\u{0020}for\u{0020}refreshment.\u{0020}Restores\u{0020}30\u{0020}stamina.\n\n\"Diluted\u{0020}mix\u{0020}of\u{0020}Nimbus\u{0020}energy\u{0020}that\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}alleviate\u{0020}tiredness\u{0020}after\u{0020}synesthesia.\u{0020}Orange\u{0020}and\u{0020}peach\u{0020}flavor\u{0020}are\u{0020}available\u{0020}to\u{0020}make\u{0020}the\u{0020}taste\u{0020}more\u{0020}acceptable,\u{0020}and\u{0020}even\u{0020}if\u{0020}a\u{0020}normal\u{0020}human\u{0020}intake\u{0020}it\u{0020}by\u{0020}mistake,\u{0020}it\u{0020}is\u{0020}completely\u{0020}harmless.\"", group = 4001, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, timelimt = "0", "0", "稀释能量合剂", "稀释过的液态尼姆比斯，使用后可恢复30点体力。\n「稀释的尼姆比斯合剂，可以稍微缓解过度使用【通感】带来的无力感。有水蜜桃和甜橙两种口味，即使普通人误饮也没有危害。」", "0"},
[110001] = {id = 110001, name = "Standard\u{0020}Energy\u{0020}Potion", icon = "icon_goods_tiliyaoji_0", quality = 3, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "A\u{0020}mixture\u{0020}with\u{0020}standard\u{0020}doses\u{0020}of\u{0020}Nimbus\u{0020}energy\u{0020}for\u{0020}refreshment.\u{0020}Restores\u{0020}50\u{0020}stamina.\n\n\"Energy\u{0020}mix\u{0020}specially\u{0020}prepared\u{0020}by\u{0020}Dr.\u{0020}Stephanie.\u{0020}Gia\u{0020}takes\u{0020}3\u{0020}flasks\u{0020}of\u{0020}it\u{0020}with\u{0020}her\u{0020}at\u{0020}all\u{0020}times.\u{0020}Compared\u{0020}to\u{0020}diluted\u{0020}mixes,\u{0020}it\u{0020}has\u{0020}a\u{0020}tint\u{0020}of\u{0020}sour\u{0020}flavor,\u{0020}perhaps\u{0020}it\u{0020}is\u{0020}added\u{0020}on\u{0020}Gia's\u{0020}request.\"", group = 4002, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, timelimt = "0", "0", "常规能量合剂", "常规剂量的尼姆比斯合剂，使用后可恢复50点体力。\n「史蒂芬妮博士特制的尼姆比斯合剂。\n吉雅的身边时常配备着三瓶。比稀释合剂多了一种酸酸的口味，似乎是根据吉雅的要求调配的。」", "0"},
[110002] = {id = 110002, name = "Condensed\u{0020}Energy\u{0020}Potion", icon = "icon_goods_tiliyaoji_1", quality = 4, use = 1, fall = "4_100001_100", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "A\u{0020}mixture\u{0020}of\u{0020}condensed\u{0020}Nimbus\u{0020}energy\u{0020}for\u{0020}refreshment.\u{0020}Restores\u{0020}100\u{0020}stamina.\n\n\"Used\u{0020}for\u{0020}rapid\u{0020}replenishment\u{0020}of\u{0020}energy\u{0020}and\u{0020}stamina\u{0020}consumed\u{0020}by\u{0020}synesthesia,\u{0020}that\u{0020}can\u{0020}be\u{0020}crucial\u{0020}at\u{0020}times.\u{0020}It\u{0020}is\u{0020}advised\u{0020}to\u{0020}prevent\u{0020}using\u{0020}the\u{0020}energy\u{0020}mix\u{0020}for\u{0020}non-combat\u{0020}situations,\u{0020}as\u{0020}Dr.\u{0020}Stephanie\u{0020}has\u{0020}introduced\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}stimulants\u{0020}into\u{0020}the\u{0020}formula,\u{0020}which\u{0020}will\u{0020}very\u{0020}likely\u{0020}cause\u{0020}insomnia.\"", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, timelimt = "0", "0", "浓缩能量合剂", "浓缩的尼姆比斯合剂，使用后可恢复100点体力。\n「快速补充使用【通感】而消耗的精神力与体力，扭转战局的关键，需要注意的是，史蒂芬妮博士在其中加入了大量的提神药物，在非战斗状态下饮用可能会导致彻夜不眠。」", "0"},
[110010] = {id = 110010, name = "Transformation\u{0020}Star\u{0020}Shards", icon = "icon_goods_shengxingsuipian", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "Contains\u{0020}highly\u{0020}potent\u{0020}level\u{0020}of\u{0020}energy.\u{0020}Used\u{0020}to\u{0020}promote\u{0020}drivers'\u{0020}Star\u{0020}Rank.\n\n\"Compatibility\u{0020}Rate\u{0020}is\u{0020}just\u{0020}a\u{0020}starting\u{0020}point\u{0020}for\u{0020}a\u{0020}Driver,\u{0020}however,\u{0020}how\u{0020}great\u{0020}and\u{0020}how\u{0020}far\u{0020}a\u{0020}Driver\u{0020}can\u{0020}achieve,\u{0020}has\u{0020}nothing\u{0020}to\u{0020}do\u{0020}with\u{0020}the\u{0020}rate.\"", group = 3000, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "幻化星碎", "蕴含着巨大的能量，可用于提升角色的星级。\n「【适格率】只是决定驾驶员的起点，但一位驾驶员最终站在什么高度，往往与【适格率】没有什么关系。」", "0"},
[110020] = {id = 110020, name = "Raw\u{0020}Resonant\u{0020}Crystal", icon = "icon_goods_gongmingyuanshi", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_sc_wzbc_01", txt = "A\u{0020}raw\u{0020}material\u{0020}used\u{0020}in\u{0020}creation\u{0020}of\u{0020}Resonance\u{0020}Gears.\n\n\"When\u{0020}standard\u{0020}issued\u{0020}gears\u{0020}are\u{0020}not\u{0020}enough\u{0020}to\u{0020}take\u{0020}down\u{0020}more\u{0020}powerful\u{0020}Sins,\u{0020}perhaps\u{0020}you'll\u{0020}need\u{0020}these......\u{0020}they\u{0020}didn't\u{0020}disappear,\u{0020}they\u{0020}just\u{0020}become\u{0020}the\u{0020}power\u{0020}of\u{0020}aid\u{0020}in\u{0020}your\u{0020}battle.\"", group = 3001, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "共鸣原石", "可用于制造共鸣装备。\n「当驾驶员常用的武装不足以应对更高级的原罪时，也许你会需要这个……共鸣原石不是消失了，它只是换了一种样子陪在驾驶员的身边。」", "0"},
[110021] = {id = 110021, name = "Resonant\u{0020}Crystalline", icon = "icon_goods_gongmingjiejingti", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_bj_gmzb_01", txt = "A\u{0020}by-product\u{0020}from\u{0020}Transformation\u{0020}Core\u{0020}processing\u{0020}that\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}upgrade\u{0020}Resonance\u{0020}Gears.\n\n\"I'm\u{0020}going\u{0020}to\u{0020}use\u{0020}my\u{0020}entire\u{0020}stocks\u{0020}of\u{0020}Resonant\u{0020}Crystalline\u{0020}to\u{0020}give\u{0020}the\u{0020}Drivers'\u{0020}gears\u{0020}an\u{0020}upgrade!\"", group = 3002, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "共鸣结晶体", "从幻化核心中提炼出的副产物，可用于强化共鸣装备。\n「我把背包中的共鸣结晶体与驾驶员身上的装备进行共鸣强化！」", "0"},
[110030] = {id = 110030, name = "Common\u{0020}Requisition\u{0020}Ticket", icon = "icon_goods_putongzhaomujuan", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Can\u{0020}be\u{0020}used\u{0020}for\u{0020}requisition\u{0020}of\u{0020}Drivers.\n\n\"For\u{0020}who\u{0020}you\u{0020}wish\u{0020}to\u{0020}encounter,\u{0020}for\u{0020}how\u{0020}you\u{0020}wish\u{0020}to\u{0020}get\u{0020}along,\u{0020}it's\u{0020}all\u{0020}upon\u{0020}your\u{0020}will,\u{0020}Navigator.\"", group = 4100, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "新锐调度券", "可以征调寻常的AVG驾驶员。\n「我希望所有领航都能弄清楚，自己的驾驶员们都是怀着怎样的心态踏上与原罪战斗的旅途，请好好引领她们。」", "0"},
[110031] = {id = 110031, name = "Elite\u{0020}Requisition\u{0020}Ticket", icon = "icon_goods_jingyingzhaomujuan", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Can\u{0020}be\u{0020}used\u{0020}for\u{0020}requisition\u{0020}of\u{0020}extraordinary\u{0020}Drivers.\n\n\"Being\u{0020}extraordinary\u{0020}-\u{0020}it\u{0020}could\u{0020}mean\u{0020}the\u{0020}Driver\u{0020}processes\u{0020}exceptional\u{0020}skills\u{0020}and\u{0020}capabilities\u{0020}of\u{0020}particular\u{0020}aspects.\"\n\"Being\u{0020}extraordinary\u{0020}-\u{0020}it\u{0020}could\u{0020}also\u{0020}mean\u{0020}the\u{0020}Driver\u{0020}has\u{0020}some\u{0020}form\u{0020}of\u{0020}defects.\"\n\"However,\u{0020}if\u{0020}it\u{0020}is\u{0020}you,\u{0020}I\u{0020}believe\u{0020}you\u{0020}will\u{0020}guide\u{0020}them\u{0020}into\u{0020}finding\u{0020}their\u{0020}own\u{0020}respective\u{0020}right\u{0020}paths......\u{0020}Remember,\u{0020}these\u{0020}seasoned\u{0020}Drivers\u{0020}who\u{0020}commit\u{0020}to\u{0020}fight\u{0020}for\u{0020}the\u{0020}world\u{0020}-\u{0020}they\u{0020}are\u{0020}heroes,\u{0020}they\u{0020}are\u{0020}soldiers,\u{0020}but\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}they\u{0020}are\u{0020}also\u{0020}emotional\u{0020}growing\u{0020}girls.\"", group = 4101, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "精英调度券", "可以征调不同寻常的AVG驾驶员。\n「不同寻常——代表着驾驶员在某些方面拥有着特别优秀的能力。」\n「不同寻常——可能也代表着这位驾驶员有着某种缺陷。」\n「不过我相信，如果是你的话，一定能引领她们找到正确的道路……请时刻谨记，这些为世界挺身而出、身经百战的驾驶员，她们是英雄，她们是战士，同时也是富有复杂情感的、正在成长的女孩。」", "0"},
[110032] = {id = 110032, name = "Ace\u{0020}Requisition\u{0020}Ticket", icon = "icon_goods_bidezhaomujuan", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Ace\u{0020}Requisition\u{0020}Ticket,\u{0020}can\u{0020}requisition\u{0020}real\u{0020}ace\u{0020}drivers.\n\"An\u{0020}ace\u{0020}is\u{0020}someone\u{0020}whose\u{0020}name\u{0020}everyone\u{0020}cheers\u{0020}when\u{0020}they\u{0020}appear\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}and\u{0020}then\u{0020}watches\u{0020}them\u{0020}effortlessly\u{0020}take\u{0020}down\u{0020}the\u{0020}fierce\u{0020}enemies\u{0020}amidst\u{0020}a\u{0020}chorus\u{0020}of\u{0020}cheers.\"\n\"But\u{0020}even\u{0020}an\u{0020}ace,\u{0020}if\u{0020}requisitioned\u{0020}to\u{0020}the\u{0020}wrong\u{0020}place\u{0020}at\u{0020}the\u{0020}wrong\u{0020}time,\u{0020}can\u{0020}lead\u{0020}to\u{0020}a\u{0020}disastrous\u{0020}defeat.\"\n\"So\u{0020}please,\u{0020}Navigator,\u{0020}do\u{0020}not\u{0020}spare\u{0020}your\u{0020}passion,\u{0020}get\u{0020}closer\u{0020}to\u{0020}them,\u{0020}understand\u{0020}them,\u{0020}and\u{0020}treat\u{0020}them\u{0020}well.\"", group = 4102, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "王牌调度券", "可以征调真正的王牌驾驶员。\n「所谓王牌就是当她们出现在战场上时所有人都会高呼她们的名字，然后在连绵的欢呼声中看着她们轻松解决原本穷凶极恶的敌人。」\n「但即使是王牌，如果在错误的时间被派遣到错误的地方所带来的结果也将是惨败。」\n「所以请领航不要吝惜自己的热情，更多地接近她们，了解她们，善待她们。」", "0"},
[110033] = {id = 110033, name = "Training\u{0020}Intent\u{0020}Letter", icon = "icon_train", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Can\u{0020}be\u{0020}used\u{0020}to\u{0020}requisition\u{0020}ten\u{0020}times\u{0020}in\u{0020}the\u{0020}special\u{0020}gacha\u{0020}\"Flame\u{0020}Ignition\u{0020}Training\".\n\"A\u{0020}folder\u{0020}containing\u{0020}ten\u{0020}training\u{0020}intent\u{0020}letters.\"", group = 4103, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "王牌調度券", "可以徵調真正的王牌駕駛員。\n「所謂王牌就是當她們出現在戰場上時所有人都會高呼她們的名字，然後在連綿的歡呼聲中看著她們輕鬆解決原本窮兇極惡的敵人。」\n「但即使是王牌，如果在錯誤的時間被派遣到錯誤的地方所帶來的結果也將是慘敗。」\n「所以請領航不要吝惜自己的熱情，更多地接近她們，瞭解她們，善待她們。」", "0"},
[110034] = {id = 110034, name = "Transcendant\u{0020}Requisition\u{0020}Ticket", icon = "icon_goods_chaoyuezhaomujuan", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Can\u{0020}be\u{0020}used\u{0020}for\u{0020}requisition\u{0020}of\u{0020}Drivers\u{0020}titled\u{0020}\"Transcendent\".\n\n\"Transcendence\u{0020}-\u{0020}the\u{0020}non-replicaple\u{0020}miracles.\u{0020}Only\u{0020}the\u{0020}Drivers\u{0020}who\u{0020}have\u{0020}achieved\u{0020}breaking\u{0020}the\u{0020}bounds\u{0020}of\u{0020}human\u{0020}be\u{0020}titled\u{0020}'Transcendent'.\"\n\"Distinguished\u{0020}from\u{0020}the\u{0020}aces\u{0020}who\u{0020}are\u{0020}considered\u{0020}the\u{0020}foundations\u{0020}of\u{0020}mankind's\u{0020}efforts,\u{0020}each\u{0020}Transcendent\u{0020}Driver\u{0020}is\u{0020}one\u{0020}greater\u{0020}possibilities\u{0020}beyond.\"\n\"Hence,\u{0020}as\u{0020}a\u{0020}Navigator,\u{0020}common\u{0020}concepts\u{0020}cannot\u{0020}define\u{0020}a\u{0020}Transcendent\u{0020}Driver.\u{0020}They\u{0020}are\u{0020}powerful,\u{0020}but\u{0020}can\u{0020}also\u{0020}be\u{0020}fragile.\"", group = 4103, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "王牌調度券", "可以徵調真正的王牌駕駛員。\n「所謂王牌就是當她們出現在戰場上時所有人都會高呼她們的名字，然後在連綿的歡呼聲中看著她們輕鬆解決原本窮兇極惡的敵人。」\n「但即使是王牌，如果在錯誤的時間被派遣到錯誤的地方所帶來的結果也將是慘敗。」\n「所以請領航不要吝惜自己的熱情，更多地接近她們，瞭解她們，善待她們。」", "0"},
