[110090] = {id = 110090, name = "Glittering\u{0020}Reverb", icon = "icon_goods_jinengqianghua_2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Valuable\u{0020}material\u{0020}required\u{0020}for\u{0020}upgrading\u{0020}skills\u{0020}of\u{0020}SSR\u{0020}Drivers.\n\n\"Strength\u{0020}of\u{0020}an\u{0020}individial\u{0020}may\u{0020}not\u{0020}be\u{0020}enough\u{0020}to\u{0020}alter\u{0020}the\u{0020}course\u{0020}of\u{0020}war,\u{0020}however,\u{0020}for\u{0020}the\u{0020}special\u{0020}ones\u{0020}among\u{0020}elite\u{0020}Drivers,\u{0020}we\u{0020}can\u{0020}have\u{0020}exceptional\u{0020}expectations\u{0020}over\u{0020}their\u{0020}growth\u{0020}and\u{0020}enhancement.\"\n\"This\u{0020}project\u{0020}aims\u{0020}to\u{0020}create\u{0020}aces\u{0020}bearing\u{0020}the\u{0020}decisive\u{0020}powers\u{0020}leading\u{0020}to\u{0020}victory.\"\n\"They\u{0020}will\u{0020}be\u{0020}our\u{0020}sword\u{0020}of\u{0020}hope\u{0020}to\u{0020}bring\u{0020}the\u{0020}end\u{0020}to\u{0020}the\u{0020}war,\u{0020}the\u{0020}war\u{0020}between\u{0020}mankind\u{0020}and\u{0020}the\u{0020}Sins.\"", group = 3202, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "极巅计划书", "用于强化训练3星角色技能强度的珍贵材料。\n「个人的力量难以改变一场战争的局势，但是总有一些特殊的驾驶员，我们可以对她们的成长报以期待。」\n「这份计划书旨在培养那些能以一己之力终结战争的驾驶员。」\n「她们将会成为终结人类与原罪之间战争的利刃。」", "0"},
[110091] = {id = 110091, name = "Violet\u{0020}Reverb", icon = "icon_goods_jinengqianghua_1", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Valuable\u{0020}material\u{0020}required\u{0020}for\u{0020}upgrading\u{0020}skills\u{0020}of\u{0020}SR\u{0020}Drivers.\n\n\"Mastering\u{0020}skills\u{0020}of\u{0020}battle\u{0020}only\u{0020}is\u{0020}not\u{0020}enough.\u{0020}Sharp\u{0020}senses\u{0020}and\u{0020}resourcefulness\u{0020}will\u{0020}further\u{0020}reinforce\u{0020}your\u{0020}tactical\u{0020}flexibility,\u{0020}going\u{0020}in-and-out\u{0020}of\u{0020}a\u{0020}dangerous\u{0020}battle\u{0020}unhindered.\"", group = 3201, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "战略简述", "用于强化训练2星角色技能强度的珍贵材料。\n「光是掌握技巧是远远不够的。能拥有洞察全局的头脑才能让自己在战场上进退自如。」", "0"},
[110092] = {id = 110092, name = "Azure\u{0020}Reverb", icon = "icon_goods_jinengqianghua_0", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Valuable\u{0020}material\u{0020}required\u{0020}for\u{0020}upgrading\u{0020}skills\u{0020}of\u{0020}R\u{0020}Drivers.\n\n\"A\u{0020}well-arranged\u{0020}training\u{0020}plan\u{0020}with\u{0020}moderate\u{0020}intensity.\"\n\"We\u{0020}can\u{0020}foresee\u{0020}this\u{0020}training\u{0020}plan\u{0020}shall\u{0020}direct\u{0020}newer\u{0020}Drivers\u{0020}breaking\u{0020}their\u{0020}own\u{0020}limits\u{0020}with\u{0020}success.\"", group = 3200, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "特训单表", "用于强化训练1星角色技能强度的珍贵材料。\n「一份安排得很充分的训练计划表，强度适中。」\n「可以预见，接受了这份训练的新人们都将蜕变成功。」", "0"},
[110093] = {id = 110093, name = "Transcendent\u{0020}Reverb", icon = "icon_goods_jinengqianghua_tongyong", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "Extraordinary\u{0020}and\u{0020}precious\u{0020}material\u{0020}required\u{0020}for\u{0020}upgrading\u{0020}skills\u{0020}of\u{0020}Transcendent\u{0020}SSR\u{0020}Drivers.\n\n\"When\u{0020}we\u{0020}fail\u{0020}again,\u{0020}the\u{0020}world's\u{0020}end\u{0020}will\u{0020}certainly\u{0020}come\u{0020}to\u{0020}us.\u{0020}All\u{0020}the\u{0020}stories\u{0020}written\u{0020}together\u{0020}with\u{0020}him,\u{0020}will\u{0020}be\u{0020}buried\u{0020}memories\u{0020}of\u{0020}the\u{0020}past\u{0020}nobody\u{0020}will\u{0020}ever\u{0020}remember.\"\n\"For\u{0020}our\u{0020}strong\u{0020}ties\u{0020}and\u{0020}bonds\u{0020}established,\u{0020}for\u{0020}one\u{0020}and\u{0020}another\u{0020}iteration\u{0020}of\u{0020}the\u{0020}world,\u{0020}for\u{0020}many\u{0020}times\u{0020}you've\u{0020}refused\u{0020}to\u{0020}give\u{0020}in\u{0020}on\u{0020}the\u{0020}journey\u{0020}of\u{0020}salvation...\"\n\"First\u{0020}it\u{0020}will\u{0020}be\u{0020}me,\u{0020}then\u{0020}it\u{0020}well\u{0020}be\u{0020}the\u{0020}rest\u{0020}of\u{0020}them\u{0020}-\u{0020}The\u{0020}existance\u{0020}of\u{0020}the\u{0020}transcendants,\u{0020}my\u{0020}existance,\u{0020}are\u{0020}the\u{0020}living\u{0020}evidences\u{0020}of\u{0020}your\u{0020}efforts\u{0020}have\u{0020}never\u{0020}been\u{0020}futile.\"", group = 3202, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, timelimt = "0", "0", "極巔計畫書", "用於強化訓練3星角色技能強度的珍貴材料。\n「個人的力量難以改變一場戰爭的局勢，但是總有一些特殊的駕駛員，我們可以對她們的成長報以期待。」\n「這份計畫書旨在培養那些能以一己之力終結戰爭的駕駛員。」\n「她們將會成為終結人類與原罪之間戰爭的利刃。」", "0"},
